INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM205KSTH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 250 voters in a city found that 145 support a proposed park renovation. The margin of error for the survey is $4\\%$. Which of the following is the best estimate of the range of the percentage of all voters in the city who support the renovation?', NULL, $lyceon_json$[{"key":"A","text":"$54\\%$ to $62\\%$"},{"key":"B","text":"$56\\%$ to $60\\%$"},{"key":"C","text":"$58\\%$ to $62\\%$"},{"key":"D","text":"$54\\%$ to $58\\%$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sample proportion is $\\frac{145}{250} = 0.58$, or $58\\%$. With a margin of error of $4\\%$, the plausible range is $58\\% - 4\\% = 54\\%$ to $58\\% + 4\\% = 62\\%$. The range $56\\%$ to $60\\%$ applies only a $2\\%$ margin on each side. The range $58\\%$ to $62\\%$ adds the margin only above the estimate. The range $54\\%$ to $58\\%$ subtracts the margin only below the estimate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20CJUAF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $f(1) = 15$ and $f(4) = 405$, what is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$45$"},{"key":"B","text":"$81$"},{"key":"C","text":"$135$"},{"key":"D","text":"$405$"}]$lyceon_json$::jsonb, 'C', NULL, E'From $f(1) = ab = 15$ and $f(4) = ab^4 = 405$, dividing gives $\\frac{ab^4}{ab} = b^3 = \\frac{405}{15} = 27$, so $b = 3$. Then $a = \\frac{15}{3} = 5$. Therefore $f(3) = 5 \\cdot 3^3 = 5 \\cdot 27 = 135$. The distractor $45$ equals $f(2) = 5 \\cdot 3^2 = 45$, from using the wrong exponent. The distractor $81$ equals $3^4$, resulting from finding $b$ correctly but computing $b^4$ without multiplying by $a$. The distractor $405$ is the given value of $f(4)$, not $f(3)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20LCJXL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values $12, 18, 18, 24, 30, 36, 36, 36, 42$. What is the mode of this data set?', NULL, $lyceon_json$[{"key":"A","text":"$18$"},{"key":"B","text":"$28$"},{"key":"C","text":"$30$"},{"key":"D","text":"$36$"}]$lyceon_json$::jsonb, 'D', NULL, E'The mode is the value that appears most frequently. The value $36$ appears $3$ times, which is more than any other value. The value $18$ appears only $2$ times and is not the most frequent. The value $28$ is the mean of the data set ($252 \\div 9 = 28$), not the mode. The value $30$ is the median (the middle value of the $9$ ordered data points), not the mode.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20PBREB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $38$. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$19\\pi$"},{"key":"B","text":"$38\\pi$"},{"key":"C","text":"$76\\pi$"},{"key":"D","text":"$361\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$. With $d = 38$, the circumference is $38\\pi$. The value $19\\pi$ results from halving the diameter to get the radius and then computing $\\pi r$ instead of $\\pi d$ or $2\\pi r$. The value $76\\pi$ results from doubling the diameter before multiplying by $\\pi$. The value $361\\pi$ comes from computing the area $\\pi r^2 = \\pi(19)^2 = 361\\pi$ instead of the circumference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
