INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21NYHEP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the larger solution to the equation $x^2 - 11x + 28 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Factor the quadratic: $x^2 - 11x + 28 = (x - 4)(x - 7) = 0$. Setting each factor equal to zero gives $x = 4$ or $x = 7$. The larger solution is $7$.', NULL, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22GK37C', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $DEF$, angle $D$ measures $47°$ and angle $E$ measures $71°$. Point $G$ lies on side $\\overline{DE}$ such that $\\overline{FG}$ bisects angle $DFE$. What is the measure, in degrees, of angle $FGE$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '78', ARRAY['78'], E'First, find angle $F$: since the angles of a triangle sum to $180°$, angle $F = 180° - 47° - 71° = 62°$. Because $\\overline{FG}$ bisects angle $DFE$, the angle $GFE = \\frac{62°}{2} = 31°$. In triangle $FGE$, the angle sum gives angle $FGE = 180° - 71° - 31° = 78°$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23XCLGT', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the following system of equations have no solution?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25QFOGO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees at a company found that 74 drink coffee only, 53 drink tea only, 31 drink both coffee and tea, and the rest drink neither. If an employee who drinks coffee is selected at random, what is the probability that this employee also drinks tea?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{31}{200}$"},{"key":"B","text":"$\\frac{31}{105}$"},{"key":"C","text":"$\\frac{31}{84}$"},{"key":"D","text":"$\\frac{31}{127}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The number of employees who drink coffee is those who drink coffee only plus those who drink both: $74 + 31 = 105$. Given that the employee drinks coffee, the probability of also drinking tea is $\\frac{31}{105}$. Using $\\frac{31}{200}$ divides by the total number of employees instead of restricting to coffee drinkers. Using $\\frac{31}{84}$ incorrectly uses $53 + 31 = 84$ (the tea-drinking total) as the denominator. Using $\\frac{31}{127}$ adds all three groups ($74 + 53$) without recognizing the overlap structure.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25RXQKF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $23$ meters and a width of $11$ meters. What is the area, in square meters, of the garden?', NULL, $lyceon_json$[{"key":"A","text":"$34$"},{"key":"B","text":"$68$"},{"key":"C","text":"$207$"},{"key":"D","text":"$253$"}]$lyceon_json$::jsonb, 'D', NULL, E'The area of a rectangle is length times width: $23 \\times 11 = 253$ square meters. The value $34$ results from adding $23 + 11$ instead of multiplying. The value $68$ results from computing the perimeter $2(23 + 11) = 68$ instead of the area. The value $207$ results from an arithmetic slip, computing $23 \\times 9$ instead of $23 \\times 11$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM263REGW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'A class of $11$ students has a mean test score of $73$. When the lowest score of $41$ is removed from the data set, what is the mean test score of the remaining $10$ students?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '76.2', ARRAY['381/5', '76.2'], E'The total of all $11$ scores is $11 \\times 73 = 803$. Removing the score of $41$ leaves a total of $803 - 41 = 762$. The mean of the remaining $10$ scores is $\\frac{762}{10} = 76.2$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM279N4BM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In right triangle $PQR$, angle $Q$ is the right angle. If $PQ = 13$ and $PR = 85$, what is $\\sin(R)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13}{84}$"},{"key":"B","text":"$\\frac{13}{85}$"},{"key":"C","text":"$\\frac{84}{85}$"},{"key":"D","text":"$\\frac{84}{13}$"}]$lyceon_json$::jsonb, 'B', NULL, E'In right triangle $PQR$ with the right angle at $Q$, the hypotenuse is $PR = 85$ and the side opposite angle $R$ is $PQ = 13$. Therefore $\\sin(R) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{13}{85}$. The value $\\frac{13}{84}$ uses the adjacent leg ($QR = 84$) in the denominator instead of the hypotenuse, which gives $\\tan(R)$. The value $\\frac{84}{85}$ is $\\cos(R)$, not $\\sin(R)$. The value $\\frac{84}{13}$ inverts the opposite and adjacent sides, giving $\\cot(R)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27Q59JU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A jar contains 11 red marbles, 7 blue marbles, and 5 green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{23}$"},{"key":"B","text":"$\\frac{7}{23}$"},{"key":"C","text":"$\\frac{11}{23}$"},{"key":"D","text":"$\\frac{7}{16}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of marbles is $11 + 7 + 5 = 23$. The probability of selecting a blue marble is the number of blue marbles divided by the total: $\\frac{7}{23}$. Selecting $\\frac{5}{23}$ confuses the count of green marbles for blue. Selecting $\\frac{11}{23}$ confuses the count of red marbles for blue. Selecting $\\frac{7}{16}$ incorrectly excludes the green marbles from the total count.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28F3BEH', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the equation $3x^2 - 10x + k = 0$ have exactly one real solution?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{10}{3}$"},{"key":"B","text":"$\\frac{25}{3}$"},{"key":"C","text":"$\\frac{100}{3}$"},{"key":"D","text":"$-\\frac{25}{3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'A quadratic equation has exactly one real solution when its discriminant equals zero. For $3x^2 - 10x + k = 0$, the discriminant is $b^2 - 4ac = (-10)^2 - 4(3)(k) = 100 - 12k$. Setting $100 - 12k = 0$ gives $k = \\frac{100}{12} = \\frac{25}{3}$. The distractor $\\frac{10}{3}$ results from using $b$ rather than $b^2$ in the discriminant formula. The distractor $\\frac{100}{3}$ omits the factor of $4$ in $4ac$, dividing $100$ by $3$ alone. The distractor $-\\frac{25}{3}$ applies an incorrect sign when solving for $k$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28GDBDI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'A surveyor at point $A$ measures the angle of elevation to the top of a building as $34°$. She walks $50$ meters directly toward the building to point $C$ and measures the angle of elevation as $57°$. What is the height of the building, to the nearest meter?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'Let $h$ be the height of the building and $d$ be the horizontal distance from point $C$ to the base of the building. From point $C$, $\\tan(57°) = \\frac{h}{d}$, so $d = \\frac{h}{\\tan(57°)}$. From point $A$, $\\tan(34°) = \\frac{h}{d + 50}$. Substituting gives $\\frac{h}{\\tan(34°)} = \\frac{h}{\\tan(57°)} + 50$. Solving for $h$: $h\\left(\\frac{1}{\\tan(34°)} - \\frac{1}{\\tan(57°)}\\right) = 50$, so $h = \\frac{50}{\\frac{1}{\\tan(34°)} - \\frac{1}{\\tan(57°)}} = \\frac{50}{1.4826 - 0.6494} = \\frac{50}{0.8332} \\approx 60$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29H8C9I', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $5$ and a height of $11$. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$55\\pi$"},{"key":"B","text":"$110\\pi$"},{"key":"C","text":"$275\\pi$"},{"key":"D","text":"$550\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi (5)^2 (11) = 275\\pi$. The value $55\\pi$ results from using $V = \\pi r h$ instead of $\\pi r^2 h$, omitting the squaring of the radius. The value $110\\pi$ results from using the lateral surface area formula $2\\pi r h = 2\\pi(5)(11) = 110\\pi$ instead of the volume formula. The value $550\\pi$ results from doubling the correct volume, possibly by confusing the formula with $2\\pi r^2 h$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AK8272', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory produces $91$ widgets in $7$ hours. At this constant rate, how many widgets does the factory produce in $13$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$104$"},{"key":"B","text":"$143$"},{"key":"C","text":"$169$"},{"key":"D","text":"$182$"}]$lyceon_json$::jsonb, 'C', NULL, E'The rate is $\\frac{91}{7} = 13$ widgets per hour, so in $13$ hours the factory produces $13 \\times 13 = 169$ widgets. The answer $104$ results from incorrectly adding $91 + 13$ rather than computing the rate. The answer $143$ comes from using an incorrect rate of $11$ widgets per hour. The answer $182$ arises from doubling $91$, which would only be correct for $14$ hours, not $13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BU986Z', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 - 9}{x^2 + 7x + 12} \\cdot \\frac{x^2 + 8x + 16}{x^2 - x - 12}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x - 3}{x - 4}$"},{"key":"B","text":"$\\frac{(x - 3)(x + 4)}{(x + 3)(x - 4)}$"},{"key":"C","text":"$\\frac{(x + 3)(x + 4)}{(x - 3)(x - 4)}$"},{"key":"D","text":"$\\frac{x - 3}{x + 3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factor each polynomial: $x^2 - 9 = (x - 3)(x + 3)$, $x^2 + 7x + 12 = (x + 3)(x + 4)$, $x^2 + 8x + 16 = (x + 4)^2$, and $x^2 - x - 12 = (x - 4)(x + 3)$. The product becomes $\\frac{(x - 3)(x + 3)}{(x + 3)(x + 4)} \\cdot \\frac{(x + 4)^2}{(x - 4)(x + 3)}$. Cancelling one $(x + 3)$ factor and one $(x + 4)$ factor yields $\\frac{(x - 3)(x + 4)}{(x + 3)(x - 4)}$. The distractor $\\frac{x - 3}{x - 4}$ over-cancels by removing both $(x + 3)$ and $(x + 4)$ entirely. The distractor $\\frac{(x + 3)(x + 4)}{(x - 3)(x - 4)}$ swaps the numerator and denominator factors. The distractor $\\frac{x - 3}{x + 3}$ cancels all $(x + 4)$ factors but keeps only one $(x + 3)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C888YM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'Three points $A(1, 8)$, $B(1, -2)$, and $C(11, 8)$ lie on a circle. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$25\\pi$"},{"key":"B","text":"$50\\pi$"},{"key":"C","text":"$100\\pi$"},{"key":"D","text":"$200\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The center of the circle is the intersection of perpendicular bisectors of two chords. The midpoint of $\\overline{AB}$ is $(1, 3)$ and $\\overline{AB}$ is vertical, so its perpendicular bisector is $y = 3$. The midpoint of $\\overline{AC}$ is $(6, 8)$ and $\\overline{AC}$ is horizontal, so its perpendicular bisector is $x = 6$. The center is $(6, 3)$. The radius is the distance from $(6, 3)$ to $(1, 8)$: $r = \\sqrt{(6-1)^2 + (3-8)^2} = \\sqrt{25 + 25} = \\sqrt{50}$. The area is $\\pi r^2 = 50\\pi$. The value $25\\pi$ results from using only one component of the distance ($\\sqrt{25} = 5$) as the radius. The value $100\\pi$ results from doubling $r^2$. The value $200\\pi$ results from using the diameter squared ($2r)^2 = 200$) in place of $r^2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2COQ3PZ', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A student has at most 13 hours per week to split between two part-time jobs. Job X pays 19 dollars per hour and job Y pays 11 dollars per hour. The student must earn at least 173 dollars per week and wants to maximize the number of hours spent at job Y. What is the maximum whole number of hours the student can work at job Y?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Let $x$ and $y$ represent hours at jobs X and Y. The constraints are $x + y \\leq 13$, $19x + 11y \\geq 173$, $x \\geq 0$, and $y \\geq 0$. To maximize $y$, minimize $x$. From the earnings constraint, $x \\geq \\frac{173 - 11y}{19}$. From the time constraint, $x \\leq 13 - y$. Setting $\\frac{173 - 11y}{19} \\leq 13 - y$ and solving: $173 - 11y \\leq 247 - 19y$, so $8y \\leq 74$, giving $y \\leq 9.25$. The maximum whole number is $9$. Verification: at $y = 9$, the student needs $x \\geq \\frac{173 - 99}{19} = \\frac{74}{19} \\approx 3.9$, and $x + 9 \\leq 13$ gives $x \\leq 4$, so $x = 4$ satisfies both constraints with earnings $19(4) + 11(9) = 175 \\geq 173$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CRT5EN', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A taxi company charges 3 dollars for the first mile and 2 dollars for each additional mile. Which function $f(m)$ represents the total charge, in dollars, for a ride of $m$ miles, where $m \\geq 1$?', NULL, $lyceon_json$[{"key":"A","text":"$f(m) = 2m + 1$"},{"key":"B","text":"$f(m) = 2m + 3$"},{"key":"C","text":"$f(m) = 3m + 2$"},{"key":"D","text":"$f(m) = 5m$"}]$lyceon_json$::jsonb, 'A', NULL, E'The first mile costs 3 dollars, and each additional mile beyond the first costs 2 dollars. For $m$ miles, the additional miles number $m - 1$, costing $2(m - 1)$ dollars. The total is $3 + 2(m - 1) = 2m + 1$. Checking: $f(1) = 3$ dollars (correct). The function $f(m) = 2m + 3$ incorrectly charges 2 dollars per mile for all miles and then adds the 3-dollar fee on top, double-counting the first mile. The function $f(m) = 3m + 2$ swaps the per-mile rate and the flat fee. The function $f(m) = 5m$ incorrectly adds both rates together and applies them to every mile.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CZL17P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'grid_in', E'A line of best fit for a data set is $y = 2.1x + 17$. According to this model, what is the predicted value of $y$ when $x = 8$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '33.8', ARRAY['169/5', '33.8'], E'Substituting $x = 8$ into the equation gives $y = 2.1(8) + 17 = 16.8 + 17 = 33.8$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D7WVLI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'From the top of a $23$-meter lighthouse, the angle of depression to a sailboat is $31°$. What is the horizontal distance, in meters, from the base of the lighthouse to the sailboat? (Round to the nearest tenth.)', NULL, $lyceon_json$[{"key":"A","text":"$11.8$"},{"key":"B","text":"$13.8$"},{"key":"C","text":"$38.3$"},{"key":"D","text":"$44.7$"}]$lyceon_json$::jsonb, 'C', NULL, E'The angle of depression equals the angle of elevation from the boat to the top of the lighthouse, which is $31°$. Using the tangent ratio, $\\tan(31°) = \\frac{23}{d}$, so $d = \\frac{23}{\\tan(31°)} \\approx \\frac{23}{0.6009} \\approx 38.3$ meters. The value $11.8$ results from computing $23 \\times \\sin(31°)$ instead of dividing by $\\tan(31°)$. The value $13.8$ results from computing $23 \\times \\tan(31°)$, which inverts the relationship. The value $44.7$ results from dividing by $\\sin(31°)$ instead of $\\tan(31°)$, which gives the line-of-sight distance rather than the horizontal distance.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D92SET', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $6x^2 + 17x - 14$?', NULL, $lyceon_json$[{"key":"A","text":"$(2x - 7)(3x + 2)$"},{"key":"B","text":"$(6x + 7)(x - 2)$"},{"key":"C","text":"$(2x + 7)(3x - 2)$"},{"key":"D","text":"$(3x + 7)(2x - 2)$"}]$lyceon_json$::jsonb, 'C', NULL, E'To factor $6x^2 + 17x - 14$, find two binomials whose product gives $6x^2$ as the leading term and $-14$ as the constant. Expanding $(2x + 7)(3x - 2)$ yields $6x^2 - 4x + 21x - 14 = 6x^2 + 17x - 14$, which matches. Expanding $(2x - 7)(3x + 2)$ gives $6x^2 - 17x - 14$, a sign error on the middle term. Expanding $(6x + 7)(x - 2)$ gives $6x^2 - 5x - 14$, an incorrect factoring setup. Expanding $(3x + 7)(2x - 2)$ gives $6x^2 + 8x - 14$, which has the wrong middle coefficient.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DFJCL6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'After a $35\\%$ discount and then a $4\\%$ sales tax applied to the discounted price, the final price of an item is $67.60$ dollars. What was the original price, in dollars, of the item?', NULL, $lyceon_json$[{"key":"A","text":"$65$"},{"key":"B","text":"$91.26$"},{"key":"C","text":"$100$"},{"key":"D","text":"$104$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $P$ be the original price. After a $35\\%$ discount the price is $0.65P$, and after $4\\%$ tax it becomes $0.65P \\times 1.04 = 0.676P$. Setting $0.676P = 67.60$ gives $P = \\frac{67.60}{0.676} = 100$ dollars. The answer $65$ results from only undoing the tax ($67.60 \\div 1.04 = 65$) without restoring the discount. The answer $91.26$ comes from multiplying $67.60 \\times 1.35$, incorrectly adding back the discount as a percentage increase. The answer $104$ results from dividing $67.60 \\div 0.65$, undoing the discount but ignoring the tax.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DR2Q8H', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of 40 students, 18 study French, 14 study Spanish, and 6 study both French and Spanish. A student is chosen at random from the class. Given that the student does NOT study French, what is the probability that the student studies Spanish?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{8}{22}$"},{"key":"B","text":"$\\frac{8}{26}$"},{"key":"C","text":"$\\frac{14}{22}$"},{"key":"D","text":"$\\frac{6}{22}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Students who study French total 18, so those who do NOT study French number $40 - 18 = 22$. Among the 14 who study Spanish, 6 also study French, so $14 - 6 = 8$ study Spanish only (and therefore do not study French). The conditional probability is $\\frac{8}{22}$. Using $\\frac{8}{26}$ incorrectly computes the non-French group as $40 - 14 = 26$, confusing Spanish for French. Using $\\frac{14}{22}$ fails to subtract the 6 overlap students from the Spanish count. Using $\\frac{6}{22}$ counts only the overlap students instead of the Spanish-only students.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FY8KAX', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'Line $p$ passes through the points $(2, 11)$ and $(5, 23)$. What is the $y$-intercept of line $p$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'The slope of line $p$ is $\\frac{23 - 11}{5 - 2} = \\frac{12}{3} = 4$. Using point-slope form with $(2, 11)$: $y - 11 = 4(x - 2)$, which simplifies to $y = 4x - 8 + 11 = 4x + 3$. The $y$-intercept is $3$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G249Y4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers at a university randomly selected 500 adults from a city and randomly assigned them to one of two groups. Group A received a daily omega-3 supplement, and Group B received a placebo. After 6 months, Group A showed a statistically significant improvement in memory test scores compared to Group B. Which of the following conclusions is best supported by the study design?', NULL, $lyceon_json$[{"key":"A","text":"The omega-3 supplement caused improved memory scores among all adults in the city."},{"key":"B","text":"The omega-3 supplement is associated with improved memory scores, but causation cannot be established because the study was observational."},{"key":"C","text":"The omega-3 supplement caused improved memory scores among the adults in the study, and this result can be generalized to the city population."},{"key":"D","text":"The omega-3 supplement caused improved memory scores among the adults in the study, but this result cannot be generalized to all adults nationwide."}]$lyceon_json$::jsonb, 'C', NULL, E'The study uses both random selection (from the city) and random assignment (to treatment groups). Random assignment allows causal inference about the treatment effect, and random selection from the city allows generalization to the city population. Claiming the result applies to all adults in the city without qualification overgeneralizes beyond the study''s scope (which found results among those sampled). Calling the study observational is incorrect because participants were randomly assigned to treatment and control. Stating the result cannot be generalized to the city contradicts the fact that participants were randomly selected from the city, which is precisely the basis for generalization to that population.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HTUL2J', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation $x^2 + y^2 - 8x + 14y + k = 0$ represents a circle with area $53\\pi$. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-12$"},{"key":"B","text":"$12$"},{"key":"C","text":"$53$"},{"key":"D","text":"$118$"}]$lyceon_json$::jsonb, 'B', NULL, E'Completing the square: $(x - 4)^2 - 16 + (y + 7)^2 - 49 + k = 0$, which gives $(x - 4)^2 + (y + 7)^2 = 65 - k$. Since the area is $53\\pi$ and area $= \\pi r^2$, we have $r^2 = 53$. Setting $65 - k = 53$ yields $k = 12$. The value $-12$ results from a sign error when solving $65 - k = 53$. The value $53$ comes from identifying $r^2 = 53$ but setting $k = r^2$ without completing the square properly. The value $118$ results from adding $65 + 53$ instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IPPQVW', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A mechanic charges a flat diagnostic fee of 47 dollars plus 31 dollars per hour of labor. A second mechanic charges no diagnostic fee but 54 dollars per hour of labor. For how many hours of labor would both mechanics charge the same total amount?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{23}{47}$"},{"key":"B","text":"$\\frac{47}{85}$"},{"key":"C","text":"$\\frac{54}{31}$"},{"key":"D","text":"$\\frac{47}{23}$"}]$lyceon_json$::jsonb, 'D', NULL, E'Setting the costs equal: $47 + 31h = 54h$. Subtracting $31h$ from both sides gives $47 = 23h$, so $h = \\frac{47}{23}$. The value $\\frac{23}{47}$ inverts the correct fraction, reflecting a gap in solving for the variable. The value $\\frac{47}{85}$ comes from incorrectly adding the hourly rates ($31 + 54 = 85$) in the denominator instead of subtracting them. The value $\\frac{54}{31}$ results from setting up a ratio of the two hourly rates rather than solving the equation for equal total cost.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LGB89B', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'What is the solution to the inequality $9x + 4 \\leq 67$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\leq 7$"},{"key":"B","text":"$x \\geq 7$"},{"key":"C","text":"$x \\leq 63$"},{"key":"D","text":"$x \\geq 63$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting 4 from both sides gives $9x \\leq 63$, and dividing both sides by 9 gives $x \\leq 7$. The distractor $x \\geq 7$ reverses the inequality direction, which is incorrect since we divided by a positive number. The distractor $x \\leq 63$ stops after subtracting 4 without dividing by 9. The distractor $x \\geq 63$ makes both errors: failing to divide and reversing the direction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MSTEJA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A scatterplot shows a linear association between the number of hours studied, $x$, and the score on a test, $y$. The line of best fit is $y = 4.7x + 53$. A student who studied for $6$ hours scored $79$ on the test. What is the residual for this student''s data point?', NULL, $lyceon_json$[{"key":"A","text":"$-2.2$"},{"key":"B","text":"$2.2$"},{"key":"C","text":"$50.8$"},{"key":"D","text":"$81.2$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted score is $4.7(6) + 53 = 28.2 + 53 = 81.2$. The residual is actual minus predicted: $79 - 81.2 = -2.2$. The value $2.2$ reverses the subtraction order, computing predicted minus actual. The value $50.8$ comes from subtracting only the slope term from the actual score ($79 - 28.2$), omitting the intercept in the prediction. The value $81.2$ is the predicted score itself, not the residual.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NU2YVJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A school had $340$ students last year. This year, the number of students increased by $15\\%$. How many students does the school have this year?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '391', ARRAY['391'], E'A $15\\%$ increase means the new enrollment is $340 \\times 1.15 = 391$ students. Equivalently, $15\\%$ of $340$ is $51$, and $340 + 51 = 391$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O4U4OK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally priced at $137$ dollars is on sale for $20\\%$ off. What is the sale price, in dollars, of the jacket?', NULL, $lyceon_json$[{"key":"A","text":"$27.40$"},{"key":"B","text":"$109.60$"},{"key":"C","text":"$117$"},{"key":"D","text":"$164.40$"}]$lyceon_json$::jsonb, 'B', NULL, E'A $20\\%$ discount on $137$ dollars gives a discount of $137 \\times 0.20 = 27.40$ dollars, so the sale price is $137 - 27.40 = 109.60$ dollars. The answer $27.40$ is only the discount amount, not the sale price. The answer $117$ comes from subtracting $20$ instead of $20\\%$. The answer $164.40$ results from adding $20\\%$ instead of subtracting it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OQGBVE', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'The line $7x - 3y = 15$ is perpendicular to line $m$, and line $m$ passes through the point $(14, -1)$. What is the $y$-intercept of line $m$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$5$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'C', NULL, E'Rewriting $7x - 3y = 15$ in slope-intercept form gives $y = \\frac{7}{3}x - 5$, so its slope is $\\frac{7}{3}$. The perpendicular slope is $-\\frac{3}{7}$. Using point-slope form with $(14, -1)$: $y + 1 = -\\frac{3}{7}(x - 14)$, giving $y = -\\frac{3}{7}x + 6 - 1 = -\\frac{3}{7}x + 5$. The $y$-intercept is $5$. The value $-7$ results from using $\\frac{3}{7}$ (reciprocal without negating) as the perpendicular slope, which yields $y = \\frac{3}{7}x - 7$. The value $-5$ comes from reading the $y$-intercept of the original line. The value $7$ results from writing $y - 1$ instead of $y + 1$ in the point-slope equation, producing $y = -\\frac{3}{7}x + 7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q19AKW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A map uses a scale where $3$ centimeters represents $19$ kilometers. Two landmarks are $7.5$ centimeters apart on the map. What is the actual distance, in kilometers, between the two landmarks?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '47.5', ARRAY['95/2', '47.5'], E'Set up the proportion $\\frac{3}{19} = \\frac{7.5}{d}$. Cross-multiplying gives $3d = 7.5 \\times 19 = 142.5$, so $d = \\frac{142.5}{3} = 47.5$ kilometers.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q47ICQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher found that cities with more ice cream shops tend to have higher rates of bicycle accidents. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Ice cream shops cause bicycle accidents."},{"key":"B","text":"Bicycle accidents cause ice cream shops to open."},{"key":"C","text":"There is an association between the number of ice cream shops and bicycle accident rates, but a causal relationship cannot be established."},{"key":"D","text":"There is no relationship between the number of ice cream shops and bicycle accident rates."}]$lyceon_json$::jsonb, 'C', NULL, E'The study is observational: the researcher observed existing data without manipulating variables. Observational studies can identify associations but cannot establish causation. Both variables likely share a lurking variable such as population size or warm weather. Claiming that ice cream shops cause accidents or that accidents cause shops to open incorrectly infers causation from correlation. Claiming no relationship contradicts the observed association.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QCKLGU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A pharmaceutical company tested a new headache medication. They recruited 120 volunteers and let each volunteer choose whether to take the medication or a placebo. After two weeks, the medication group reported fewer headaches. A company spokesperson claimed the medication reduces headaches. Which of the following is the most significant flaw in this study?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of 120 is too small to draw any conclusion."},{"key":"B","text":"Participants were not randomly assigned to treatment and control groups, so confounding variables may explain the results."},{"key":"C","text":"The study lasted only two weeks, which is too short for any medication to take effect."},{"key":"D","text":"The study should have included a third group that received no treatment at all."}]$lyceon_json$::jsonb, 'B', NULL, E'The critical flaw is that participants self-selected into the medication or placebo group rather than being randomly assigned. Without random assignment, differences between the groups (such as severity of headaches or health-consciousness) could confound the results, making it impossible to attribute the outcome to the medication. A sample size of 120 is not inherently too small for a clinical study. Two weeks can be sufficient for a headache medication study. Adding a no-treatment group would not address the self-selection bias.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
