INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QN8VX5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A researcher wants to estimate the proportion of residents in a town who support a new library tax. A random sample of 400 residents yields a sample proportion of $0.47$ with a margin of error of $0.05$ at a $95\\%$ confidence level. If the researcher instead surveyed 1,600 residents (keeping all other factors the same), which of the following would be the approximate margin of error?', NULL, $lyceon_json$[{"key":"A","text":"$0.0125$"},{"key":"B","text":"$0.025$"},{"key":"C","text":"$0.01$"},{"key":"D","text":"$0.05$"}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is inversely proportional to the square root of the sample size. Quadrupling the sample size from 400 to 1,600 doubles the square root ($\\sqrt{1600} = 40$ vs. $\\sqrt{400} = 20$), which halves the margin of error: $\\frac{0.05}{2} = 0.025$. The value $0.0125$ divides the margin of error by 4, confusing direct proportionality with the square-root relationship. The value $0.01$ applies an incorrect reduction factor. The value $0.05$ assumes sample size has no effect on the margin of error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QP8GXL', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $3x + 11 = 47$?', NULL, $lyceon_json$[{"key":"A","text":"$-12$"},{"key":"B","text":"$12$"},{"key":"C","text":"$\\frac{47}{3}$"},{"key":"D","text":"$\\frac{58}{3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtracting $11$ from both sides gives $3x = 36$, and dividing both sides by $3$ gives $x = 12$. The value $-12$ results from a sign error when dividing. The value $\\frac{47}{3}$ comes from dividing $47$ by $3$ without first subtracting $11$, stopping at an intermediate step. The value $\\frac{58}{3}$ comes from incorrectly adding $11$ to $47$ instead of subtracting, then dividing by $3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RIB4VB', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'A linear function $f$ satisfies $f(f(1)) = 19$ and $f(f(4)) = 31$. If the $y$-intercept of $f$ is positive, what is the $y$-intercept of $f$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Let $f(x) = ax + b$. Then $f(f(x)) = a(ax + b) + b = a^2x + ab + b$. From the given conditions: $a^2(1) + ab + b = 19$ and $a^2(4) + ab + b = 31$. Subtracting the first equation from the second gives $3a^2 = 12$, so $a^2 = 4$ and $a = \\pm 2$. If $a = 2$: substituting into the first equation gives $4 + 2b + b = 19$, so $3b = 15$ and $b = 5$. If $a = -2$: substituting gives $4 - 2b + b = 19$, so $-b = 15$ and $b = -15$. Since the $y$-intercept must be positive, $b = 5$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RPJZRP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'grid_in', E'The function $g$ is defined by $g(x) = 3x^2 - 7x + 11$. What is the value of $g(2)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Substituting $x = 2$ into $g(x) = 3x^2 - 7x + 11$ gives $g(2) = 3(2)^2 - 7(2) + 11 = 3(4) - 14 + 11 = 12 - 14 + 11 = 9$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RRP2O9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A chemist mixes solution A and solution B in the ratio $5{:}9$ to create a compound. Solution A costs $23$ dollars per liter and solution B costs $11$ dollars per liter. What is the total cost, in dollars, of the solutions needed to make $42$ liters of the compound?', NULL, $lyceon_json$[{"key":"A","text":"$214$"},{"key":"B","text":"$642$"},{"key":"C","text":"$652$"},{"key":"D","text":"$786$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio $5{:}9$ has $14$ total parts. Each part corresponds to $\\frac{42}{14} = 3$ liters, so solution A is $5 \\times 3 = 15$ liters and solution B is $9 \\times 3 = 27$ liters. The total cost is $15 \\times 23 + 27 \\times 11 = 345 + 297 = 642$ dollars. The answer $214$ comes from computing $5 \\times 23 + 9 \\times 11 = 214$ without scaling the ratio to $42$ liters. The answer $652$ results from an arithmetic error in multiplying. The answer $786$ results from reversing the ratio, assigning $27$ liters to solution A and $15$ liters to solution B.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SBUWMG', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $11x^2 + 5x - 4x^2 + 13x$?', NULL, $lyceon_json$[{"key":"A","text":"$7x^2 + 18x$"},{"key":"B","text":"$7x^2 + 8x$"},{"key":"C","text":"$15x^2 + 18x$"},{"key":"D","text":"$15x^2 + 8x$"}]$lyceon_json$::jsonb, 'A', NULL, E'Combining like terms, the $x^2$ terms are $11x^2 - 4x^2 = 7x^2$ and the $x$ terms are $5x + 13x = 18x$, giving $7x^2 + 18x$. The distractor $7x^2 + 8x$ results from subtracting $13 - 5$ instead of adding the $x$ coefficients. The distractor $15x^2 + 18x$ comes from incorrectly adding $11 + 4$ instead of subtracting for the $x^2$ terms. The distractor $15x^2 + 8x$ combines both errors.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TA50Z2', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $\\frac{3(2x - 7)}{4} + 5 = 14$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '19/2', ARRAY['19/2', '9.5'], E'Subtracting $5$ from both sides gives $\\frac{3(2x - 7)}{4} = 9$. Multiplying both sides by $4$ gives $3(2x - 7) = 36$. Dividing both sides by $3$ gives $2x - 7 = 12$. Adding $7$ to both sides gives $2x = 19$. Dividing by $2$ gives $x = \\frac{19}{2}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U54UOY', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $f$ has a rate of change of $-4$. If $f(3) = 17$, what is $f(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$-12$"},{"key":"B","text":"$5$"},{"key":"C","text":"$17$"},{"key":"D","text":"$29$"}]$lyceon_json$::jsonb, 'D', NULL, E'Since $f$ is linear with slope $-4$, we have $f(x) = -4x + b$. Substituting $f(3) = 17$ gives $-12 + b = 17$, so $b = 29$. Therefore $f(0) = 29$. The value $-12$ is the intermediate product $-4 \\cdot 3$ and represents stopping before completing the calculation. The value $5$ results from using a positive slope of $4$ instead of $-4$: $12 + b = 17$ gives $b = 5$. The value $17$ mistakes $f(3)$ for $f(0)$, ignoring that the function changes between those inputs.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U9AH1X', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'Data were collected on the amount of fertilizer applied, $x$, in grams, and the resulting tomato yield, $y$, in kilograms. The least-squares regression line is $y = 0.13x + 2.9$, and the correlation coefficient is $r = 0.87$. Which of the following is the best interpretation of the slope of the regression line in this context?', NULL, $lyceon_json$[{"key":"A","text":"For each additional kilogram of yield, the amount of fertilizer used increases by $0.13$ grams."},{"key":"B","text":"For each additional gram of fertilizer, the predicted yield increases by $2.9$ kilograms."},{"key":"C","text":"For each additional gram of fertilizer, the predicted yield increases by $0.13$ kilograms."},{"key":"D","text":"Approximately $87\\%$ of the variation in yield is explained by the amount of fertilizer applied."}]$lyceon_json$::jsonb, 'C', NULL, E'The slope of $0.13$ means that for each additional gram of fertilizer ($x$), the model predicts the yield ($y$) increases by $0.13$ kilograms. Stating that yield increases by $0.13$ grams per kilogram reverses the roles of the independent and dependent variables. Claiming the yield increases by $2.9$ kilograms confuses the slope with the $y$-intercept. Stating that $87\\%$ of variation is explained describes neither the slope nor $r$ correctly; $r = 0.87$ is the correlation coefficient, and the coefficient of determination would be $r^2 \\approx 0.76$, not $0.87$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"unit_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UAGJQ8', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A theater sells adult tickets for 11 dollars each and child tickets for 7 dollars each. On a particular evening, 200 tickets were sold for a total of 1,744 dollars. How many adult tickets were sold?', NULL, $lyceon_json$[{"key":"A","text":"$79$"},{"key":"B","text":"$86$"},{"key":"C","text":"$98$"},{"key":"D","text":"$114$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $a$ be adult tickets and $c$ be child tickets. The system is $a + c = 200$ and $11a + 7c = 1{,}744$. Substituting $c = 200 - a$ into the revenue equation: $11a + 7(200 - a) = 1{,}744$, which simplifies to $11a + 1{,}400 - 7a = 1{,}744$, so $4a = 344$ and $a = 86$. The distractor 79 results from a subtraction error when computing $1{,}744 - 1{,}400$. The distractor 98 arises from an incorrect equation setup. The distractor 114 equals the number of child tickets ($200 - 86 = 114$), which answers the wrong quantity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VIE0HT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'The ages, in years, of $7$ employees at a company are $23, 29, 31, 34, 38, 41$, and $53$. The employee aged $53$ leaves and is replaced by a new employee aged $32$. Which of the following correctly describes the effect on the mean and median of the employees'' ages?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases and the median stays the same."},{"key":"B","text":"The mean stays the same and the median decreases."},{"key":"C","text":"The mean increases and the median decreases."},{"key":"D","text":"The mean decreases and the median decreases."}]$lyceon_json$::jsonb, 'D', NULL, E'Original mean: $\\frac{23+29+31+34+38+41+53}{7} = \\frac{249}{7} \\approx 35.6$. Original median (4th value): $34$. After replacing $53$ with $32$, the sorted set is $23, 29, 31, 32, 34, 38, 41$. New mean: $\\frac{228}{7} \\approx 32.6$, which is lower. New median (4th value): $32$, which is also lower. Both the mean and the median decrease. Saying only the mean decreases while the median stays the same overlooks that inserting $32$ shifts the middle value. Saying the mean stays the same ignores that the sum decreased by $21$. Saying the mean increases reverses the direction of the change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VNFGCD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A right circular cylinder has a total surface area of $414\\pi$ square centimeters and a height of $14$ centimeters. What is the radius, in centimeters, of the cylinder?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'The total surface area of a cylinder is $S = 2\\pi r^2 + 2\\pi r h$. Setting this equal to $414\\pi$ and dividing both sides by $2\\pi$ gives $r^2 + rh = 207$. Substituting $h = 14$: $r^2 + 14r = 207$, or $r^2 + 14r - 207 = 0$. Factoring: $(r + 23)(r - 9) = 0$. Since the radius must be positive, $r = 9$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VVJL9Q', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $JKL$, the measure of angle $J$ is $43°$ and the measure of angle $K$ is $72°$. What is the measure, in degrees, of angle $L$?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$65$"},{"key":"C","text":"$115$"},{"key":"D","text":"$137$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of any triangle is $180°$. Therefore, angle $L = 180° - 43° - 72° = 65°$. The value $29$ results from subtracting $43$ from $72$ rather than using the angle sum property. The value $115$ comes from adding the two given angles ($43 + 72$) instead of subtracting their sum from $180$. The value $137$ comes from subtracting only angle $J$ from $180°$ and neglecting to subtract angle $K$ as well.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WSJM6R', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'Two independent random samples were taken in a school district. In Sample 1, $62\\%$ of 300 parents favored year-round schooling with a margin of error of $5\\%$. In Sample 2, $71\\%$ of 300 parents favored year-round schooling with a margin of error of $4\\%$. Based on these results, which of the following is a valid conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The two confidence intervals do not overlap, so there is a significant difference between the two samples."},{"key":"B","text":"The two confidence intervals overlap, so it is plausible that the true proportion of parents who favor year-round schooling is the same for both populations."},{"key":"C","text":"Since both samples have the same size, their results must be identical."},{"key":"D","text":"Since Sample 2 has a smaller margin of error, its result is correct and Sample 1 is wrong."}]$lyceon_json$::jsonb, 'B', NULL, E'Sample 1 gives a confidence interval of $57\\%$ to $67\\%$. Sample 2 gives a confidence interval of $67\\%$ to $75\\%$. These intervals share the boundary value $67\\%$, so they do overlap. When confidence intervals overlap, we cannot conclude the population proportions are different; it is plausible they are the same. Claiming the intervals do not overlap miscalculates the endpoints. Equal sample sizes do not require identical results. A smaller margin of error does not make one result correct and another wrong.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X3874N', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $3x + 7y = 49$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$\\frac{49}{3}$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting $x = 0$ gives $7y = 49$, so $y = 7$. The value $3$ confuses the coefficient of $x$ for the $y$-intercept. The value $\\frac{49}{3}$ results from finding the $x$-intercept instead (setting $y = 0$ gives $3x = 49$). The value $49$ mistakes the constant on the right side for the intercept without dividing by the coefficient of $y$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XF2CQM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. One of the alternate interior angles measures $(3x + 17)°$ and the other measures $(5x - 29)°$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$23$"},{"key":"C","text":"$24$"},{"key":"D","text":"$46$"}]$lyceon_json$::jsonb, 'B', NULL, E'Alternate interior angles formed by parallel lines and a transversal are congruent, so $3x + 17 = 5x - 29$. Solving gives $46 = 2x$, thus $x = 23$. The value $6$ results from a sign error when collecting terms (getting $-12 = 2x$ instead of $46 = 2x$ and taking the absolute value). The value $24$ comes from incorrectly treating the angles as supplementary ($3x + 17 + 5x - 29 = 180$), which yields $8x = 192$ and $x = 24$. The value $46$ comes from solving $2x = 46$ but reporting $46$ instead of dividing by $2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YVLN2G', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The system of equations $y = x^2 - 5x + 3$ and $y = 2x - 9$ has two solutions. What is the sum of the $x$-coordinates of these solutions?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$3$"},{"key":"C","text":"$7$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting the two expressions for $y$ equal: $x^2 - 5x + 3 = 2x - 9$, which simplifies to $x^2 - 7x + 12 = 0$. Factoring gives $(x - 3)(x - 4) = 0$, so $x = 3$ and $x = 4$. The sum of the $x$-coordinates is $3 + 4 = 7$. The distractor $-7$ applies the wrong sign when using the sum-of-roots formula. The distractor $3$ gives only one of the two roots. The distractor $12$ confuses the sum with the product of the roots.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YX0GDT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = -2x^2 + 20x - 32$. What is the maximum value of $h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-32$"},{"key":"B","text":"$5$"},{"key":"C","text":"$18$"},{"key":"D","text":"$50$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since the leading coefficient is negative, the parabola opens downward and the vertex gives the maximum. The $x$-coordinate of the vertex is $x = -\\frac{b}{2a} = -\\frac{20}{2(-2)} = 5$. Evaluating: $h(5) = -2(25) + 20(5) - 32 = -50 + 100 - 32 = 18$. The distractor $-32$ is simply the constant term of the function, not the maximum. The distractor $5$ is the $x$-coordinate of the vertex, not the maximum value. The distractor $50$ comes from only partially completing the square and using $-2(x^2 - 10x) = -2(x - 5)^2 + 50$ without subtracting the constant $32$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20NKJ1C', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of ancient Mesopotamian cylinder seals housed at the Walters Art ______ one of the most comprehensive assemblages of such artifacts outside of Iraq, encompassing examples from the Akkadian, Babylonian, and Assyrian periods.', $lyceon_json$[{"key":"A","text":"Museum represent"},{"key":"B","text":"Museum are representing"},{"key":"C","text":"Museum represents"},{"key":"D","text":"Museum have represented"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is "collection," which is singular, so the verb must also be singular. The intervening prepositional phrases "of ancient Mesopotamian cylinder seals" and "housed at the Walters Art Museum" do not change the number of the subject. The plural verb "represent" incorrectly agrees with the nearer noun "seals" rather than the true subject. Similarly, "are representing" and "have represented" use plural verb forms that fail to agree with the singular subject "collection."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22EEXSF', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The Caspian seal is the only marine mammal found in the Caspian Sea. Unlike most other seal species, which migrate over vast oceanic distances, the Caspian seal remains within this landlocked body of water year-round. _______ the species has developed unique physiological adaptations to the Caspian Sea''s fluctuating salinity levels, which range from nearly fresh water in the north to highly saline conditions in the south.', $lyceon_json$[{"key":"A","text":"Accordingly,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that the Caspian seal remains year-round in a single body of water, and the sentence following the blank describes physiological adaptations to that specific environment. The logical relationship is cause-and-effect: because the seal stays in the Caspian Sea, it has developed adaptations to its conditions. "Accordingly," correctly signals this consequential relationship. "In contrast," wrongly implies that the adaptations oppose the preceding information rather than following from it. "Nevertheless," incorrectly suggests that the adaptations are surprising given the prior information, but the passage presents no tension between staying in one place and adapting to it. "Meanwhile," implies mere simultaneity without the causal connection the passage establishes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23N27SI', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Art historian Miwon Kwon has argued that site-specific art underwent three conceptual shifts between the 1960s and the 1990s. In its earliest form, site-specificity referred to works physically integrated into a particular location—a sculpture designed for a specific plaza, for example. By the late 1970s, the concept expanded to include institutional critique, where the ''site'' was not a physical place but the network of economic and social conventions governing museums and galleries. In the 1990s, a third model emerged in which the site became a discursive theme—gentrification, labor, or community identity—that could be engaged across multiple physical locations. Kwon cautions, however, that these three models are not strictly sequential; contemporary artists frequently operate within more than one framework simultaneously, and the boundaries between the models remain contested among critics.', $lyceon_json$[{"key":"A","text":"Kwon traces three evolving conceptions of site-specificity in art while noting that these frameworks overlap and coexist rather than forming a neat historical progression."},{"key":"B","text":"Kwon argues that institutional critique represented the most important development in site-specific art because it shifted attention from physical spaces to social systems."},{"key":"C","text":"The passage primarily examines how gentrification and labor issues became the dominant subjects of site-specific art during the 1990s."},{"key":"D","text":"Kwon contends that the concept of site-specificity has become so broad that it no longer serves as a useful category for classifying contemporary art."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Kwon''s framework of three evolving conceptions of site-specificity—physical, institutional, and discursive—while emphasizing her caveat that these models coexist and their boundaries are contested. The answer capturing both the three shifts and their overlap accurately states the main idea. The claim that institutional critique was the most important development distorts the passage, which presents all three models without ranking them. The focus on gentrification and labor as dominant subjects seizes on examples mentioned in passing rather than the passage''s overarching argument. The assertion that site-specificity has lost its usefulness as a category goes beyond anything Kwon argues in the passage; she notes overlap and contestation but does not dismiss the concept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23QMGBD', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Geochemist Lina Sjöberg proposed in 2018 that microbial communities in subglacial lakes beneath the East Antarctic ice sheet could metabolize iron sulfide minerals, releasing sulfate ions into the meltwater. Subsequent drilling at Lake Vostok recovered water samples with sulfate concentrations three times higher than what abiotic weathering models predicted. However, isotopic analysis by Dmitri Volkov''s team in 2022 revealed that the sulfate''s oxygen-isotope signature was consistent with volcanic hydrothermal input rather than biological sulfur oxidation, suggesting that Sjöberg''s microbial hypothesis may not be the primary explanation.', $lyceon_json$[{"key":"A","text":"It presents a hypothesis, describes evidence that initially appeared to support it, and then introduces findings that complicate it."},{"key":"B","text":"It contrasts two researchers' methodologies and concludes that one is superior to the other."},{"key":"C","text":"It describes a geological discovery, proposes a practical application, and identifies an obstacle to implementing it."},{"key":"D","text":"It traces the chronological development of a technology used in Antarctic research."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first introduces Sjöberg''s microbial metabolism hypothesis, then presents sulfate data that seemed to confirm it, and finally introduces Volkov''s isotopic findings that offer an alternative explanation. The choice describing a hypothesis, apparent supporting evidence, and complicating findings accurately captures this three-part structure. The methodology comparison choice is wrong because the passage does not evaluate which researcher''s methods are better. The practical application choice is wrong because the passage concerns a scientific hypothesis about natural processes, not any applied technology. The chronological technology development choice is wrong because the passage tracks the evolution of a scientific claim, not a technology.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23YYPXE', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Folklorist Emeka Okafor argues that the oral genealogies maintained by Igbo village historians serve a dual function. On one level, they preserve factual lineage records essential for inheritance disputes. On another, they ________ communal identity by embedding each family''s narrative within a larger mythic framework that links present-day clans to ancestral founders who, according to tradition, negotiated the original division of farmland with the earth deity Ala.', $lyceon_json$[{"key":"A","text":"consolidate"},{"key":"B","text":"quantify"},{"key":"C","text":"deplete"},{"key":"D","text":"quarantine"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes oral genealogies embedding family narratives into a larger mythic framework, thereby strengthening and unifying communal identity. "Consolidate" means to combine or strengthen into a more unified whole, which captures how individual family stories are woven into a collective identity. "Quantify" means to measure or express as a numerical value, which makes no sense applied to communal identity formed through mythic narrative. "Deplete" means to exhaust or reduce, which contradicts the passage''s description of identity being built up through these genealogies. "Quarantine" means to isolate to prevent spread, which is incoherent when applied to the process of embedding narratives within a shared framework.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23ZNPMD', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes a difference in how the authors of the two texts interpret the significance of the same phenomenon?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25ASOHK', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A historian argues that medieval Islamic astronomers did not merely preserve Greek astronomical knowledge but actively refined and corrected it. Which finding from the passage, if true, would most directly support this argument?', E'The relationship between Greek and Islamic astronomy is often characterized as one of transmission: scholars in Baghdad translated Ptolemy''s Almagest into Arabic in the ninth century, preserving it for later European rediscovery. However, recent scholarship has complicated this narrative. Al-Battani, working in Raqqa around 900 CE, recalculated the obliquity of the ecliptic and obtained a value of 23°35'', correcting Ptolemy''s figure of 23°51''—al-Battani''s measurement was closer to the modern accepted value. In thirteenth-century Maragha, Nasir al-Din al-Tusi developed a geometric device known as the Tusi couple, which resolved a longstanding mathematical inconsistency in Ptolemy''s planetary models without abandoning geocentric cosmology. Copernicus later used a mathematically identical construction in De Revolutionibus, though whether he encountered al-Tusi''s work remains debated. Meanwhile, the observatory at Samarkand under Ulugh Beg in the fifteenth century produced a star catalog with positional accuracies surpassing those of Tycho Brahe''s catalog compiled over a century later, though Brahe''s catalog covered more stars.', $lyceon_json$[{"key":"A","text":"Scholars in Baghdad translated the Almagest into Arabic during the ninth century, ensuring the survival of Ptolemy's work."},{"key":"B","text":"Copernicus may have been influenced by al-Tusi's geometric construction, though the connection remains unproven."},{"key":"C","text":"Al-Battani corrected Ptolemy's measurement of the ecliptic's obliquity to a value closer to the modern figure, and al-Tusi resolved a mathematical inconsistency in Ptolemy's planetary models."},{"key":"D","text":"Ulugh Beg's star catalog covered fewer stars than Tycho Brahe's later catalog."}]$lyceon_json$::jsonb, 'C', NULL, E'The argument is that Islamic astronomers actively refined and corrected Greek astronomy. The evidence that al-Battani improved Ptolemy''s ecliptic measurement and al-Tusi fixed a mathematical flaw in Ptolemy''s models directly demonstrates correction and refinement of Greek work. The translation of the Almagest supports the preservation narrative the historian is arguing against, not the refinement claim. The possible influence on Copernicus is tangential—it concerns the later transmission of Islamic ideas to Europe, not whether Islamic astronomers improved upon Greek astronomy. The detail about Ulugh Beg''s catalog covering fewer stars than Brahe''s actually highlights a limitation of the Islamic work and does not support the refinement argument.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25C3OB3', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The ability of certain deep-sea cephalopods to alter not only the color but also the texture of their skin—a capability that scientists believe evolved independently in at least three cephalopod ______ researchers who study convergent evolution, as it suggests that the selective pressures of the deep ocean environment consistently favor this particular adaptive strategy.', $lyceon_json$[{"key":"A","text":"lineages—fascinate"},{"key":"B","text":"lineages—have fascinated"},{"key":"C","text":"lineages—are fascinating"},{"key":"D","text":"lineages—fascinates"}]$lyceon_json$::jsonb, 'D', NULL, E'The subject of the sentence is "the ability," which is singular. The long intervening phrase—including the prepositional phrases "of certain deep-sea cephalopods" and "of their skin" and the em dash parenthetical about three cephalopod lineages—separates the subject from its verb but does not change the subject''s number. The singular verb "fascinates" correctly agrees with "the ability." The plural forms "fascinate," "have fascinated," and "are fascinating" all incorrectly treat a nearby plural noun such as "cephalopods" or "lineages" as the subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26UV62X', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Linguist Shana Poplack''s study of French-English code-switching in Ottawa-Hull found that bilingual speakers do not insert foreign-language words randomly into their sentences. Instead, switches between languages occur overwhelmingly at syntactic boundaries—between clauses, between a verb and its complement, or between a determiner and a noun phrase—where the grammars of both languages happen to align. Switches that would violate the grammatical rules of either language are extremely rare in natural speech. This pattern suggests that code-switching ________', $lyceon_json$[{"key":"A","text":"is a grammatically constrained behavior governed by the structural rules of both languages, rather than a sign of linguistic deficiency."},{"key":"B","text":"occurs exclusively in communities where both languages share the same word order and morphological structure."},{"key":"C","text":"is gradually replacing monolingual speech in all bilingual communities worldwide."},{"key":"D","text":"was first documented by Poplack in Ottawa-Hull and has not been observed in other language pairs."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage demonstrates that code-switching follows grammatical rules of both languages and avoids structural violations, which logically implies it is a rule-governed, competent linguistic behavior rather than random or deficient speech. The claim that code-switching occurs exclusively where languages share word order and morphology overstates the passage—it says switches happen where grammars align at specific points, not that the languages must be structurally identical overall. The assertion that code-switching is replacing monolingual speech worldwide introduces a sweeping claim entirely absent from the passage. The suggestion that Poplack''s study is the only documentation of code-switching is contradicted by the passage''s framing, which treats the phenomenon as a known subject of linguistic research.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28DFW8G', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'Entomologist Raquel Fuentes has cataloged over 340 species of beetles in the cloud forests of central Veracruz. Many of these species were previously unknown to science. <u>One specimen, collected from beneath the bark of a decaying Liquidambar tree at 1,870 meters elevation, possesses mandibles unlike those of any described beetle genus.</u> Fuentes plans to publish a formal taxonomic description of this specimen in an upcoming issue of the Journal of Coleopterology.', $lyceon_json$[{"key":"A","text":"It provides a specific example that illustrates the novelty of Fuentes's discoveries."},{"key":"B","text":"It explains the methodology Fuentes used to locate new beetle species."},{"key":"C","text":"It challenges a widely accepted theory about beetle distribution in cloud forests."},{"key":"D","text":"It summarizes the overall findings of Fuentes's cataloging project."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence singles out one particular specimen with unique mandibles, serving as a concrete example of the previously unknown species mentioned in the preceding sentence. The choice stating it provides a specific example illustrating the novelty of the discoveries captures this function. The methodology choice is wrong because the sentence describes the specimen''s characteristics, not Fuentes''s collection methods. The challenge choice is wrong because no existing theory is mentioned or disputed in the passage. The summary choice is wrong because the sentence highlights one specimen rather than summarizing the full scope of 340 cataloged species.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B1FKPM', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologist Renata Voss has argued that the ceremonial earthworks at Poverty Point in northeastern Louisiana were constructed over a span of roughly seventy years, reflecting a gradual communal effort. A team led by geomorphologist Tristram Kidder, however, found that soil composition data from the mounds indicate rapid, continuous deposition. _______ Kidder''s team concluded that each major earthwork was likely completed within a matter of weeks, not decades.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"On this basis,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"Regardless,"}]$lyceon_json$::jsonb, 'B', NULL, E'Kidder''s team discovered soil composition evidence indicating rapid deposition, and from that evidence they drew a conclusion about the speed of construction. "On this basis," correctly signals that the conclusion follows from the previously stated evidence. "For instance," incorrectly frames the conclusion as an example of the soil data rather than a conclusion drawn from it. "Similarly," wrongly implies that the conclusion merely parallels the soil finding rather than being derived from it. "Regardless," incorrectly suggests the conclusion was reached despite or irrespective of the evidence, when in fact the evidence directly supports it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CU744Z', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'By the time the archaeological team arrived at the site in central Anatolia, unseasonable rains ______ much of the exposed stratigraphy, forcing the researchers to spend their first three weeks reconstructing the soil layers from photographic records taken the previous season.', $lyceon_json$[{"key":"A","text":"were eroding"},{"key":"B","text":"had eroded"},{"key":"C","text":"have eroded"},{"key":"D","text":"eroded"}]$lyceon_json$::jsonb, 'B', NULL, E'The construction "by the time the archaeological team arrived" establishes a past reference point, and the erosion was completed before that arrival. The past perfect tense ("had eroded") is required to indicate an action finished before another past event. The past progressive ("were eroding") incorrectly implies the erosion was ongoing at the moment of arrival, contradicting the passage''s indication that the damage was already done. The present perfect ("have eroded") places the action in relation to the present, not to a past reference point. The simple past ("eroded") fails to establish the correct temporal sequence showing the erosion preceded the arrival.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D7LJOQ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Marine biologist Keiko Tanizaki has spent over a decade studying the migratory patterns of leatherback sea turtles in the western Pacific. Her 2019 monograph demonstrated that ocean temperature fluctuations ________ the turtles'' nesting schedules by as much as three weeks, a finding that reshaped conservation timelines across seven island nations.', $lyceon_json$[{"key":"A","text":"displaced"},{"key":"B","text":"canceled"},{"key":"C","text":"shifted"},{"key":"D","text":"rotated"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage describes nesting schedules being moved earlier or later by up to three weeks due to temperature changes. "Shifted" correctly conveys a temporal adjustment of a schedule. "Displaced" implies physical removal from a location, not a temporal change, making it incoherent in this context. "Canceled" wrongly suggests the schedules were eliminated entirely, which contradicts the passage''s statement that they moved by three weeks. "Rotated" implies circular or spinning movement, which is nonsensical when applied to a timeline.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ENRJEV', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1998, marine archaeologists discovered the wreck of a seventeenth-century merchant vessel in the Baltic Sea. The ship''s cargo hold contained more than four thousand ceramic ______ were so well preserved by the cold, low-oxygen waters that their original glazes remained intact.', $lyceon_json$[{"key":"A","text":"tiles; which"},{"key":"B","text":"tiles, which"},{"key":"C","text":"tiles. Which"},{"key":"D","text":"tiles, that"}]$lyceon_json$::jsonb, 'B', NULL, E'The clause beginning with "which" is a nonrestrictive relative clause providing additional information about all the ceramic tiles. Nonrestrictive clauses introduced by "which" require a comma before them. A semicolon before "which" would create a sentence fragment after the semicolon, since a relative clause cannot stand alone as an independent clause. A period before "Which" similarly produces a fragment. Using "that" with a preceding comma is incorrect because "that" introduces restrictive clauses, which by convention are not set off by commas.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FE8R43', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Neuroscientist Kaori Taniguchi has demonstrated that exposure to enriched environments increases dendritic branching in the hippocampus of adult rodents, a finding widely cited as evidence of neuroplasticity. Taniguchi''s own subsequent research, however, revealed that these structural changes do not necessarily correlate with improvements in spatial memory tasks. _______ she has cautioned that dendritic remodeling may reflect a general stress response to novelty rather than a targeted mechanism for enhanced learning.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"On the contrary,"},{"key":"C","text":"For this reason,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage presents Taniguchi''s finding that structural brain changes do not necessarily improve spatial memory, and the sentence following the blank describes her caution — an interpretive conclusion drawn from that finding. "For this reason," correctly signals that her caution is motivated by the disconnect she observed between dendritic changes and memory performance. "In other words," incorrectly implies that the final sentence merely restates the prior finding in different language, but it actually introduces a new interpretive claim about the nature of dendritic remodeling. "On the contrary," wrongly signals direct opposition to the preceding sentence, when in fact the caution builds upon rather than contradicts the finding about memory tasks. "Specifically," incorrectly implies that the final sentence narrows or details the preceding claim, but it instead offers a broader alternative explanation for the observed changes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GBT1GC', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Carefully analyzing the spectral signatures of seventeen exoplanetary atmospheres, ______ trace amounts of phosphine in the atmosphere of a super-Earth orbiting a red dwarf star thirty-nine light-years from our solar system.', $lyceon_json$[{"key":"A","text":"Dr. Renata Vasquez identified"},{"key":"B","text":"trace amounts were identified by Dr. Renata Vasquez as"},{"key":"C","text":"the identification by Dr. Renata Vasquez revealed"},{"key":"D","text":"it was Dr. Renata Vasquez who identified"}]$lyceon_json$::jsonb, 'A', NULL, E'The opening participial phrase "Carefully analyzing the spectral signatures of seventeen exoplanetary atmospheres" must modify the noun that immediately follows the comma—the grammatical subject of the main clause. Since a person performed the analysis, that person must be the subject. Only the option placing the researcher''s name as the subject correctly attaches the modifier. Making "trace amounts" the subject creates a dangling modifier, since trace amounts cannot analyze spectral signatures. Similarly, making "the identification" the subject is illogical, as an identification cannot perform analysis. The expletive construction beginning with "it" also dangles the modifier, since "it" does not refer to the person who did the analyzing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H1VSDN', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'A marine biologist hypothesizes that deep-sea bioluminescent organisms use light emission primarily as a predator-avoidance mechanism rather than for attracting prey. Which finding from the passage, if emphasized, would most effectively support this hypothesis?', E'Bioluminescence—the production of light by living organisms—occurs in roughly 76 percent of deep-sea species surveyed below 1,000 meters in the Monterey Bay canyon. Researchers have cataloged at least five distinct functions of bioluminescence in these ecosystems. Some squid species release luminous ink clouds when threatened, creating a glowing decoy that allows the squid to escape into darkness. Certain jellyfish emit bright flashes upon contact with a predator, a behavior called burglar-alarm signaling, which attracts larger secondary predators that may attack the original predator. Anglerfish, by contrast, dangle a bioluminescent lure to attract small fish toward their jaws. Dragonfish use far-red bioluminescence as a covert searchlight invisible to most other deep-sea organisms, enabling them to spot prey without being detected. Finally, many midwater crustaceans produce ventral light patterns that match the dim downwelling light from above, a form of counter-illumination camouflage that hides their silhouette from predators below.', $lyceon_json$[{"key":"A","text":"Anglerfish use a bioluminescent lure to draw small fish toward their mouths."},{"key":"B","text":"Roughly 76 percent of deep-sea species below 1,000 meters exhibit bioluminescence."},{"key":"C","text":"Squid release luminous ink decoys when threatened, jellyfish use burglar-alarm flashes against predators, and crustaceans employ counter-illumination camouflage to hide from predators below."},{"key":"D","text":"Dragonfish use far-red light as a covert searchlight to locate prey without being detected by other organisms."}]$lyceon_json$::jsonb, 'C', NULL, E'The hypothesis holds that bioluminescence functions primarily for predator avoidance. The combination of squid decoy clouds, jellyfish burglar-alarm signals, and crustacean counter-illumination camouflage provides three independent examples of bioluminescence used defensively against predators, which most effectively supports the hypothesis. The anglerfish lure is an example of prey attraction, which directly contradicts the hypothesis. The statistic about 76 percent prevalence establishes how common bioluminescence is but says nothing about its function. The dragonfish searchlight is a predatory tool for finding prey covertly, supporting a prey-hunting function rather than a predator-avoidance function.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HNYAL9', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'In a 2019 study of wildfire recovery in the Sierra Nevada, ecologist Marcus Okafor found that ponderosa pine seedlings recolonized burned areas within three years when seed-bearing trees stood within forty meters of the burn perimeter. In plots where the nearest surviving ponderosa pine was more than ninety meters away, however, shrub species such as whitethorn ceanothus dominated for over a decade, effectively preventing conifer reestablishment. _______ Okafor has proposed that post-fire management should prioritize preserving remnant seed trees at close intervals rather than relying on broadcast seeding programs, which disperse seeds uniformly but cannot replicate the density-dependent germination advantages of proximity to mature trees.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"By comparison,"},{"key":"D","text":"Granted,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage establishes a causal chain: proximity to surviving seed trees determines whether pine seedlings or shrubs dominate after wildfire. Okafor''s management proposal follows directly from this evidence — because proximity matters, management should focus on preserving remnant seed trees. "Consequently," correctly signals that the proposal is a logical outcome of the research findings. "In addition," incorrectly treats the proposal as supplementary information rather than a conclusion derived from the preceding evidence. "By comparison," wrongly implies a parallel or contrast between two comparable items, when the passage moves from evidence to a recommendation. "Granted," incorrectly frames the proposal as a concession, suggesting Okafor is acknowledging a counterpoint, when in fact the proposal flows from the findings without conceding anything.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I5BI8V', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Stavanger in Norway have found that the texture of food influences how much people eat. In a 2021 study, participants were given two versions of the same soup: one smooth and one with small vegetable chunks. Those who ate the chunky version consumed, on average, 23 percent less than those who ate the smooth version. The researchers concluded that textured foods require more chewing, which slows eating and gives the brain more time to register satiety signals.', $lyceon_json$[{"key":"A","text":"Food texture affects consumption by influencing how quickly people feel full."},{"key":"B","text":"Smooth soups are nutritionally inferior to chunky soups."},{"key":"C","text":"Norwegian researchers have pioneered new methods for studying hunger."},{"key":"D","text":"Chewing speed is the sole factor that determines how much a person eats."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a study showing that textured food leads to less consumption because chewing slows eating and allows satiety signals to reach the brain. The answer stating that food texture affects consumption by influencing fullness captures this central idea. The claim that smooth soups are nutritionally inferior is unsupported—the passage discusses quantity consumed, not nutritional value. The suggestion that Norwegian researchers pioneered new methods mischaracterizes the passage, which focuses on findings rather than methodology innovation. The assertion that chewing speed is the sole determinant of consumption overstates the passage''s claim, which identifies texture as one influential factor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2IZGQRU', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an article about the ecological role of sea otters for a science magazine. The student wants to present a contrast between the condition of kelp forests with and without sea otters. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JKNBZ7', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Priya Vasudeva has cataloged over 340 previously undocumented beetle species in the cloud forests of central ______ findings have prompted the Indonesian Ministry of Environment to designate three new protected research zones in the region.', $lyceon_json$[{"key":"A","text":"Sulawesi, her"},{"key":"B","text":"Sulawesi her"},{"key":"C","text":"Sulawesi; her"},{"key":"D","text":"Sulawesi; and her"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage contains two independent clauses: one ending with the location name and another beginning with a possessive pronoun and the noun "findings." A semicolon correctly joins two closely related independent clauses. A comma alone between two independent clauses produces a comma splice, which is not standard. Omitting all punctuation creates a run-on sentence. Using a semicolon followed by the coordinating conjunction "and" is non-standard; coordinating conjunctions pair with commas, not semicolons, when joining independent clauses.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LNPKCX', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'In a 2021 analysis of municipal water infrastructure across eleven midwestern counties, civil engineer Priya Dasgupta found that aging pipe networks do not simply deteriorate at a uniform rate. Instead, corrosion accelerates in unpredictable surges once the zinc coating is breached, meaning that maintenance teams cannot rely on fixed inspection intervals but must ________ their monitoring protocols to account for these abrupt transitions.', $lyceon_json$[{"key":"A","text":"adapt"},{"key":"B","text":"abandon"},{"key":"C","text":"commemorate"},{"key":"D","text":"replicate"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that fixed inspection intervals are insufficient because corrosion accelerates unpredictably, so monitoring protocols must be modified to respond to these changes. "Adapt" means to adjust something to suit new conditions, which precisely fits the need to change protocols in response to variable corrosion rates. "Abandon" implies discarding protocols altogether, but the passage indicates protocols need adjustment, not elimination. "Commemorate" means to honor or memorialize something, which is nonsensical in the context of monitoring procedures. "Replicate" means to duplicate exactly, which contradicts the passage''s point that the existing fixed approach is inadequate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LXO78G', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In the 1970s, ecologist Daniel Janzen proposed that tropical mountains act as stronger barriers to species movement than temperate mountains of the same height. Because tropical organisms experience minimal seasonal temperature variation, they develop narrow thermal tolerances. A tropical species living at 800 meters elevation, for example, may be unable to cross a 2,400-meter pass that a temperate species—accustomed to wide seasonal swings—could traverse with little difficulty. Recent physiological studies of tropical beetles and lizards have largely confirmed Janzen''s hypothesis, showing that their critical thermal maxima are often only 4 to 7 degrees Celsius above their habitat''s mean temperature.', $lyceon_json$[{"key":"A","text":"Tropical species tend to have narrow thermal tolerances, which makes tropical mountains more effective barriers to their dispersal than equivalent temperate mountains."},{"key":"B","text":"Daniel Janzen was the first scientist to study how mountains affect animal migration patterns across different climate zones."},{"key":"C","text":"Tropical beetles and lizards are more vulnerable to extinction from climate change than their temperate counterparts."},{"key":"D","text":"Mountains in tropical regions are generally taller than mountains in temperate regions, creating greater obstacles for wildlife."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Janzen''s hypothesis that tropical mountains are stronger dispersal barriers because tropical organisms have narrow thermal tolerances due to minimal seasonal variation, and it notes that recent research supports this idea. The answer about narrow thermal tolerances making tropical mountains more effective barriers accurately captures this central point. The claim that Janzen was the first to study mountain effects on migration overstates the passage, which says he proposed a specific hypothesis—not that he was the first in the broader field. The suggestion about extinction vulnerability introduces a topic the passage never addresses. The assertion that tropical mountains are taller contradicts the passage, which explicitly compares mountains of the same height.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M18F9C', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although seismologists have long known that the Cascadia Subduction Zone is capable of producing magnitude 9.0 ______ recent paleoseismic evidence suggests that such events occur at irregular intervals averaging roughly 243 years, with the last major rupture having taken place in January 1700.', $lyceon_json$[{"key":"A","text":"earthquakes; recent"},{"key":"B","text":"earthquakes. Recent"},{"key":"C","text":"earthquakes: recent"},{"key":"D","text":"earthquakes, recent"}]$lyceon_json$::jsonb, 'D', NULL, E'The clause beginning with "Although" is a subordinate (dependent) clause, so a comma is the correct punctuation to separate it from the main clause that follows ("recent paleoseismic evidence suggests..."). A semicolon is incorrect because semicolons join two independent clauses, and the "Although" clause is not independent. A period would leave "Although seismologists have long known..." as a sentence fragment. A colon requires a grammatically independent clause before it, but the "Although" clause is subordinate and therefore cannot precede a colon.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M610US', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economists studying the adoption of rooftop solar panels in Queensland, Australia, observed a pattern that standard cost-benefit models failed to predict. Between 2010 and 2018, households in suburbs where at least 19 percent of homes already had solar installations adopted panels at nearly triple the rate of households in demographically identical suburbs where fewer than 5 percent of homes had panels—even when electricity prices differed by less than 2 percent between the two groups. The visibility of existing installations, rather than financial calculations alone, appeared to drive adoption decisions. However, the researchers also found that this peer effect plateaued sharply: once neighborhood adoption exceeded approximately 37 percent, the rate of new installations dropped to levels comparable to low-adoption suburbs. The researchers propose that this plateau occurs because ________', $lyceon_json$[{"key":"A","text":"after a threshold of neighborhood adoption is reached, remaining non-adopters are disproportionately those whose properties are physically unsuitable for panels or who are ideologically resistant to the technology, making them largely unresponsive to peer influence."},{"key":"B","text":"electricity prices in high-adoption suburbs eventually fell so dramatically that the financial returns on new solar installations became negative."},{"key":"C","text":"the visibility of solar panels decreases as more are installed because residents stop noticing them as a novel feature of the neighborhood."},{"key":"D","text":"government subsidies for solar panels were withdrawn in 2015, causing adoption rates to decline uniformly across all Queensland suburbs regardless of existing installation density."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that peer visibility drives adoption but that this effect plateaus at around 37 percent. The most logical explanation is that remaining non-adopters at that point are systematically different—either physically unable to install panels or resistant to adoption—making them unresponsive to the same peer influence that motivated earlier adopters. The claim about electricity prices becoming negative introduces a financial mechanism the passage explicitly ruled out as a major factor, since price differences between groups were minimal. The suggestion that panels become unnoticed addresses visibility but fails to explain why the adoption rate drops back to low-adoption-suburb levels rather than simply leveling off. The assertion about withdrawn subsidies introduces an external event not mentioned in the passage and would predict uniform decline everywhere, contradicting the passage''s finding that the plateau was specific to high-adoption suburbs.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
