INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2P5CPTQ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Urban ecologists studying bird populations in Minneapolis found that American robins in city parks begin their dawn chorus an average of 27 minutes earlier than robins in nearby rural woodlands. The researchers noted that urban parks are illuminated by streetlights and building lights throughout the night, creating ambient light levels roughly 6 to 11 times higher than those in the rural sites. Because robins rely on light cues to initiate singing, the researchers suggest that ________', $lyceon_json$[{"key":"A","text":"urban robins have evolved a genetically distinct circadian rhythm that differs fundamentally from that of rural robins."},{"key":"B","text":"artificial light pollution in cities triggers the robins' dawn chorus prematurely by simulating earlier daybreak conditions."},{"key":"C","text":"robins in rural woodlands are declining in number because they begin singing later than urban robins."},{"key":"D","text":"the dawn chorus has no adaptive function for robins and is merely a response to random environmental stimuli."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage establishes that urban robins sing earlier, that cities have much higher artificial light levels, and that robins use light cues to initiate singing. The logical completion is that artificial light simulates earlier daybreak and triggers premature singing. The claim about genetic divergence goes far beyond the passage, which describes a behavioral response to light rather than evolutionary change. The suggestion that rural robins are declining introduces a population claim entirely unsupported by the passage. The assertion that the dawn chorus lacks adaptive function contradicts the passage''s implication that singing is a purposeful light-triggered behavior.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PLVQ17', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the research vessel Kaimana completed its three-year survey of hydrothermal vents along the Mid-Atlantic Ridge—a survey that yielded the discovery of nineteen previously unknown chemosynthetic ______ the scientific community was particularly struck by the finding that several of these organisms appeared to metabolize hydrogen sulfide at temperatures exceeding 150 degrees Celsius.', $lyceon_json$[{"key":"A","text":"organisms—the"},{"key":"B","text":"organisms, the"},{"key":"C","text":"organisms; the"},{"key":"D","text":"organisms. The"}]$lyceon_json$::jsonb, 'A', NULL, E'The parenthetical aside "a survey that yielded the discovery of nineteen previously unknown chemosynthetic organisms" is introduced by an em dash after "Ridge." To properly close this parenthetical, a matching em dash is required before the main clause resumes. Using a comma would create asymmetric punctuation, since the parenthetical was opened with an em dash, not a comma. A semicolon is incorrect because the entire passage up to this point is a subordinate clause beginning with "When," and a semicolon requires an independent clause on each side. A period would leave the "When" clause as a sentence fragment.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
