INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UP1R57', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the third sentence in the text?', E'Economic historian Nadia Bowen has argued that the expansion of credit unions in rural Appalachia during the 1930s was driven less by federal policy than by local fraternal organizations that pooled members'' savings. Her analysis of ledger books from seventeen counties in West Virginia shows that fraternal orders disbursed small agricultural loans at rates below those of any commercial bank in the region. Bowen acknowledges that federal deposit insurance, introduced in 1933, reduced the risk of bank runs and thereby made all lending institutions more stable, but she contends that this stabilization benefited commercial banks more than credit unions, which had already secured depositor trust through their fraternal governance structures.', $lyceon_json$[{"key":"A","text":"It introduces a qualification that Bowen addresses in order to strengthen her broader argument."},{"key":"B","text":"It provides statistical evidence that directly supports Bowen's central claim about fraternal organizations."},{"key":"C","text":"It describes a counterexample that undermines Bowen's thesis about the origins of credit union growth."},{"key":"D","text":"It shifts the focus of the passage from economic history to contemporary banking regulation."}]$lyceon_json$::jsonb, 'A', NULL, E'The third sentence concedes that federal deposit insurance stabilized all lending institutions, but immediately pivots to argue that this stabilization helped commercial banks more than credit unions, thereby reinforcing Bowen''s original claim about fraternal organizations'' independent role. The choice identifying a qualification addressed to strengthen the broader argument captures this concede-and-rebut structure. The statistical evidence choice is wrong because the third sentence discusses federal deposit insurance rather than presenting data from ledger books. The counterexample choice is wrong because Bowen does not present the federal insurance point as something that undermines her thesis; she argues it actually supports her distinction. The contemporary regulation choice is wrong because the passage remains focused on 1930s economic history throughout.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XTFQJ2', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief report about the Svalbard Global Seed Vault for a geography class. The student wants to emphasize the vault''s purpose. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z29DPQ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a proposal for a history seminar arguing that the economic impact of the 1783 Laki eruption in Iceland extended well beyond Scandinavia. The student wants to introduce this argument to an audience that may be unfamiliar with the eruption. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZS6D88', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A student claims that exposure to natural daylight improves office workers'' sleep quality. Which finding, if true, would most directly support this claim?', E'Workplace design researchers have increasingly studied the relationship between natural light exposure and employee well-being. A 2019 survey of 437 office workers in Portland, Oregon, found that employees whose desks were within 4 meters of a window reported higher job satisfaction than those seated in interior cubicles. Separately, a controlled study at a telecommunications company in Sacramento measured sleep patterns using wrist-worn actigraphy devices over 14 days. Workers in offices with large windows slept an average of 46 minutes longer per night and had fewer nighttime awakenings than colleagues in windowless offices. Researchers attributed this difference partly to the role of natural light in regulating circadian melatonin cycles.', $lyceon_json$[{"key":"A","text":"Workers near windows in the Portland survey reported higher job satisfaction scores."},{"key":"B","text":"Workers in windowed Sacramento offices slept 46 minutes longer and experienced fewer nighttime awakenings than those in windowless offices."},{"key":"C","text":"The Portland survey included 437 participants from a variety of departments."},{"key":"D","text":"Wrist-worn actigraphy devices were used to measure sleep patterns over a 14-day period."}]$lyceon_json$::jsonb, 'B', NULL, E'The claim concerns natural daylight improving sleep quality. The finding that windowed-office workers slept longer and had fewer awakenings directly supports this claim by linking daylight exposure to measurable sleep improvements. The Portland survey finding about job satisfaction addresses a different outcome—satisfaction, not sleep—so it does not support the specific claim. The detail about 437 participants describes the study''s sample size, which is methodological context rather than evidence for the sleep-quality claim. The mention of actigraphy devices describes the measurement tool used, not a finding about daylight''s effect on sleep.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
