$$y \\leq -2x + 13$$', NULL, $lyceon_json$[{"key":"A","text":"$(3, 8)$"},{"key":"B","text":"$(0, -10)$"},{"key":"C","text":"$(1, 5)$"},{"key":"D","text":"$(5, 2)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $(1, 5)$: the first inequality gives $5 > 4(1) - 9 = -5$, which is true, and the second gives $5 \\leq -2(1) + 13 = 11$, which is also true. The pair $(3, 8)$ fails the second inequality because $8 \\leq -2(3) + 13 = 7$ is false. The pair $(0, -10)$ fails the first inequality because $-10 > 4(0) - 9 = -9$ is false. The pair $(5, 2)$ fails the first inequality because $2 > 4(5) - 9 = 11$ is false.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);



